contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: try owner withdraw of an arbitrary amount (must be top-level calls)
    function run(uint withdrawAmount) public payable {
        // Observe initial public values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Precondition: only test meaningful amounts (can't withdraw more than balance for transfer to succeed)
        require(withdrawAmount <= beforeBalance);

        bool didRevert;
        // top-level try call to withdraw on c
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: if call succeeded (owner withdraw of <= balance), then c.balance does NOT increase and depositsCount unchanged.
        // If it reverted, depositsCount must still be unchanged (withdraw can't increment depositsCount).
        assert((!didRevert && afterBalance <= beforeBalance && afterDeposits == beforeDeposits) || (didRevert && afterDeposits == beforeDeposits));
    }

    // allow receiving Ether when c.withdraw transfers to this contract
    receive() external payable { }
}

